def find(text_lines, block):
    n = len(block); hits = [i for i in range(len(text_lines) - n + 1) if text_lines[i:i + n] == block]
    return hits

plan, bad, done = [], [], []
for it in ITEMS:
    p = it["f"]
    if "new_file" in it:
        plan.append((p, None, zlib.decompress(base64.b64decode(it["new_file"])).decode())); continue
    if not os.path.exists(p):
        bad.append(p + " (missing)"); continue
    raw = open(p, "rb").read().decode()
    crlf = "\r\n" in raw
    lines = raw.replace("\r\n", "\n").split("\n")
    edits = []
    already = 0
    for k, h in enumerate(it["hunks"]):
        ok = False
        for cut in range(0, 10):
            lo, tr = min(cut, h["lead"]), min(cut, h["trail"])
            o = h["old"][lo:len(h["old"]) - tr]; nw = h["new"][lo:len(h["new"]) - tr]
            hits = find(lines, o)
            if len(hits) == 1:
                edits.append((hits[0], len(o), nw)); ok = True; break
            if len(hits) == 0 and len(find(lines, nw)) == 1:
                already += 1; ok = True; break
        if not ok:
            bad.append(f"{p} hunk {k + 1}")
    if already == len(it["hunks"]):
        done.append(p); continue
    if already:
        bad.append(f"{p} (partly patched already)")
    plan.append((p, (lines, edits, crlf), None))
if bad:
    print("REFUSED - nothing changed. These spots differ from what the patch expects:")
    for b in bad: print("  ", b)
    sys.exit(1)
for p, ed, newfile in plan:
    if newfile is not None:
        open(p, "w", newline="\n").write(newfile); continue
    lines, edits, crlf = ed
    for start, n, nw in sorted(edits, key=lambda e: -e[0]):
        lines[start:start + n] = nw
    if not os.path.exists(p + ".pre3545.bak"):
        os.replace(p, p + ".pre3545.bak")
    open(p, "wb").write(("\r\n" if crlf else "\n").join(lines).encode())
    if p.endswith(".py"):
        py_compile.compile(p, doraise=True)
for p in done: print("already patched:", p)
print("v3.5.45 applied OK (includes v3.5.43 + v3.5.44; backups: *.pre3545.bak)")
